// Task 4.3: grade calculation using a when expression// Average Calculatorimport kotlin.system.exitProcessimport kotlin.math.roundToIntfun main(args: Array<String>) {    if (args.size != 3) {        println("Error enter 3 grades")        exitProcess(1)    }    val num1 = args[0].toFloat()    val num2 = args[1].toFloat()    val num3 = args[2].toFloat()    val average = (num1 + num2 + num3) / 3    when (average.roundToInt()) { // range type must always match to ensure compile        in 0..39 -> println("Your mark is ${average.roundToInt()}:Fail" )        in 40..69 -> println("Your mark is ${average.roundToInt()}: Pass")        in 70..100 -> println("Your mark is ${average.roundToInt()}: Distinction")    }}